function rulesFor(kind, style = null) {
  const norm = canonicalLayoutId(kind);
  const base = MOTION_PRESETS[norm]?.rules || STYLE_RULES[kind] || STYLE_RULES[norm] || STYLE_RULES['impact-slam'];
  const maxWords = style && Number(style.maxWords) > 0 ? Math.round(Number(style.maxWords)) : 0;
  return maxWords ? { ...base, maxWords: Math.max(base.minWords || 1, maxWords) } : base;
}

function paletteFor(kind, style = {}) {
  const norm = canonicalLayoutId(kind);
  const base = MOTION_PRESETS[norm]?.palette || PALETTES[norm] || PALETTES['impact-slam'];
  const customHero = style.highlightColor && style.highlightColor.toLowerCase() !== (style.color || '').toLowerCase();
  return {
    ink: style.color || base.ink,
    hero: customHero ? style.highlightColor : base.hero,
    accent: style.color2 || base.accent,
    mute: base.mute,
  };
}

function wordFill(token, kind, index, pal) {
  const norm = canonicalLayoutId(kind);
  if (token.role === 'hero' || token.role === 'current') return pal.hero;
  const raw = token.raw || token.text;
  if (isFillerWord(raw)) return pal.mute;
  if (PUNCH.has(bareWord(raw))) return pal.accent;
  if (['sticker-bomb', 'elastic-pop', 'box-builder'].includes(norm)) {
    return [pal.ink, pal.accent, pal.hero][index % 3];
  }
  return pal.ink;
}

