function phraseSeed(words) {
  let h = 2166136261;
  for (const w of words) {
    const raw = String(w.text || '');
    for (let i = 0; i < raw.length; i++) h = Math.imul(h ^ raw.charCodeAt(i), 16777619);
    h = Math.imul(h ^ Math.round((w.start || 0) * 100), 16777619);
  }
  return Math.abs(h) >>> 0;
}

