export function normalizeWords(cue) {
  if (cue.words && cue.words.length) {
    return cue.words.map((w, i) => ({
      id: i,
      text: String(w.word || w.text || '').trim(),
      start: Number(w.start ?? w.startTime) || 0,
      end: Number(w.end ?? w.endTime) || 0,
    })).filter((w) => w.text);
  }
  const parts = String(cue.text || '').split(/\s+/).filter(Boolean);
  const start = Number(cue.start ?? cue.startTime) || 0;
  const end = Number(cue.end ?? cue.endTime) || start + Math.max(1, parts.length) * 0.36;
  const span = (end - start) / Math.max(1, parts.length);
  return parts.map((text, i) => ({
    id: i,
    text,
    start: start + i * span,
    end: start + (i + 1) * span,
  }));
}

function bareWord(text) {
  return String(text || '').replace(/[^A-Za-z0-9']/g, '').toLowerCase();
}

export function isFillerWord(text) {
  const bare = bareWord(text);
  return !bare || FILLERS.has(bare);
}

export function emphasisScore(word, index, total) {
  const bare = bareWord(word.text);
  if (!bare || FILLERS.has(bare)) return -1;
  let score = Math.min(bare.length, 12) * 1.2;
  const adverb = /ly$/i.test(bare) && total > 2;
  if (adverb) score -= 3.5;
  else if (index === 0 || index === total - 1) score += 1.8;
  if (/[!?]/.test(word.text)) score += 3;
  if (bare.length >= 6) score += 2.2;
  if (bare.length <= 2) score -= 1.5;
  if (PUNCH.has(bare)) score += 2.5;
  return score;
}

export function pickHeroId(words) {
  if (!words.length) return -1;
  let best = -1;
  let bestScore = -Infinity;
  for (let i = 0; i < words.length; i++) {
    const score = emphasisScore(words[i], i, words.length);
    if (score > bestScore) {
      bestScore = score;
      best = words[i].id;
    }
  }
  if (bestScore < 0) {
    let longest = words[0];
    for (const w of words) if (w.text.length > longest.text.length) longest = w;
    return longest.id;
  }
  return best;
}

export function groupPhrases(words, maxWords = 6, gap = 0.38) {
  const phrases = [];
  let cur = [];
  for (const w of words) {
    const prev = cur[cur.length - 1];
    const punct = prev && /[.!?,;:…]$/.test(prev.text) && cur.length >= 2;
    const timed = prev && (w.start - prev.end) >= gap;
    if (cur.length && (cur.length >= maxWords || punct || timed)) {
      phrases.push(cur);
      cur = [];
    }
    cur.push(w);
  }
  if (cur.length) phrases.push(cur);
  return phrases;
}

function lastSpokenIndex(words, time) {
  let idx = -1;
  for (let i = 0; i < words.length; i++) if (time >= words[i].start) idx = i;
  return idx;
}

export function activePhrase(words, time, kind, style = null) {
  const rules = rulesFor(kind, style);
  if (!words.length) return [];
  if (rules.window === 'rolling') {
    const spoken = lastSpokenIndex(words, time);
    const pool = spoken < 0 ? words.slice(0, 1) : words.slice(0, spoken + 1);
    return pool.slice(-rules.maxWords);
  }
  const phrases = groupPhrases(words, rules.maxWords, rules.gap);
  if (!phrases.length) return words.slice(0, rules.maxWords);
  const spoken = lastSpokenIndex(words, time);
  if (spoken < 0) return phrases[0];
  const id = words[spoken].id;
  for (const phrase of phrases) if (phrase.some((w) => w.id === id)) return phrase;
  return phrases[phrases.length - 1];
}

function windowChangeTime(words, time, kind, style = null) {
  const now = activePhrase(words, time, kind, style);
  if (!now.length) return words[0]?.start ?? 0;
  const rules = rulesFor(kind, style);
  if (rules.window === 'rolling') {
    return now[now.length - 1].start;
  }
  return now[0].start;
}

function currentWordId(phrase, time) {
  const i = lastSpokenIndex(phrase, time);
  return i < 0 ? phrase[0]?.id ?? -1 : phrase[i].id;
}

