// 1. Hype Drop
function layoutHypeDrop(phrase, ctx, env) {
  const { W, H, style, heroId } = env;
  const base = baseFont(style, W, H) * 1.22;
  const lines = phrase.length <= 2 ? [phrase] : [phrase.slice(0, Math.ceil(phrase.length / 2)), phrase.slice(Math.ceil(phrase.length / 2))];
  const sizes = lines.map((line) => line.map((w) => base * (w.id === heroId ? 2.25 : 1.05)));
  const roles = lines.map((line) => line.map((w) => (w.id === heroId ? 'hero' : 'support')));
  const a = anchorPoint(style, W, H, 'hype-drop');
  const tokens = placeLines(ctx, lines, sizes, roles, style, 'hype-drop', a.x, a.y, 0.05);
  tokens.forEach((t) => {
    t.rot = -2.5;
    t.effect = 'hype-drop';
    if (t.role === 'hero') {
      t.accentColor = style.color2 || style.highlightColor || '#ff1379';
    }
  });
  return fitSafe(tokens, W, H);
}

// 2. Candy Pop
function layoutCandyPop(phrase, ctx, env) {
  const { W, H, style, heroId } = env;
  const base = baseFont(style, W, H) * 1.14;
  const lines = phrase.length <= 2 ? [phrase] : [phrase.slice(0, 1), phrase.slice(1, -1), phrase.slice(-1)].filter((l) => l.length > 0);
  const sizes = lines.map((line) => line.map((w) => base * (w.id === heroId ? 1.95 : 1.15)));
  const roles = lines.map((line) => line.map((w) => (w.id === heroId ? 'hero' : 'support')));
  const a = anchorPoint(style, W, H, 'candy-pop');
  const tokens = placeLines(ctx, lines, sizes, roles, style, 'candy-pop', a.x, a.y, 0.12);
  const palette = ['#ff499e', '#ffe600', '#70e000', '#00f5d4', '#9d4edd'];
  tokens.forEach((t, i) => {
    t.effect = 'candy-pop';
    t.candyColor = palette[i % palette.length];
  });
  return fitSafe(tokens, W, H);
}

