const LAYOUTS = {
  'hype-drop': layoutHypeDrop,
  'candy-pop': layoutCandyPop,
  'flash-card': layoutFlashCard,
  'emoji-burst': layoutEmojiBurst,
  'chrome-jelly': layoutChromeJelly,
  'text-rush': layoutTextRush,
  'impact-slam': layoutImpactSlam,
  'glass-caption': layoutGlassCaption,
  'marker-swipe': layoutMarkerSwipe,
  'focus-rack': layoutFocusRack,
  'elastic-pop': layoutElasticPop,
  'box-builder': layoutBoxBuilder,
  'luxury-serif': layoutLuxurySerif,
  'sticker-bomb': layoutStickerBomb,
  'magnetic-words': layoutMagneticWords,
  'cutout-type': layoutCutoutType,
  'whisper-scream': layoutWhisperScream,
  'digital-scramble': layoutDigitalScramble,
  'underline-chase': layoutUnderlineChase,
  'neon-tube': layoutNeonTube,
  'terminal-error': layoutTerminalError,
  'gradient-sweep': layoutGradientSweep,
  'vhs-track': layoutVhsTrack,
  'ink-script': layoutInkScript,
  // Legacy aliases
  'hero-word': layoutImpactSlam,
  'stacked-poster': layoutBoxBuilder,
  'editorial-chaos': layoutWhisperScream,
  'kinetic-sentence': layoutGradientSweep,
  'floating-focus': layoutFocusRack,
  'punch-cut': layoutImpactSlam,
  'genz-sticker': layoutStickerBomb,
  'retro-vhs': layoutVhsTrack,
  'geek-terminal': layoutTerminalError,
  'old-broadsheet': layoutLuxurySerif,
  'cursive-ink': layoutInkScript,
  'comic-burst': layoutElasticPop,
  'y2k-chrome': layoutNeonTube,
  'magazine-rule': layoutCutoutType,
  'signal-sweep': layoutDigitalScramble,
  'ribbon-trace': layoutUnderlineChase,
};

export function computeLayout(ctx, phrase, env) {
  const norm = canonicalLayoutId(env.kind);
  const fn = MOTION_PRESETS[norm]?.layout || LAYOUTS[norm] || LAYOUTS[env.kind] || layoutImpactSlam;
  return finishTokens(fn(phrase, ctx, env), norm, env.style);
}

// ---------------------------------------------------------------------------
// Animation Transforms
// ---------------------------------------------------------------------------
function enterPose(token, time, kind, style = {}, env = null) {
  const norm = canonicalLayoutId(kind);
  const mp = MOTION_PRESETS[norm];
  if (mp) return mp.enter(token, time, style, motionKnobs(style), env);
  const hero = token.role === 'hero' || token.role === 'current';
  const dur = {
    'hype-drop': 0.16,
    'candy-pop': 0.18,
    'flash-card': 0.20,
    'emoji-burst': 0.18,
    'chrome-jelly': 0.24,
    'text-rush': 0.14,
    'impact-slam': 0.16,
    'elastic-pop': 0.18,
    'sticker-bomb': 0.18,
    'terminal-error': 0.14,
    'digital-scramble': 0.16,
    'whisper-scream': 0.20,
    'glass-caption': 0.24,
    'luxury-serif': 0.32,
    'focus-rack': 0.26,
    'cutout-type': 0.22,
    'marker-swipe': 0.20,
    'gradient-sweep': 0.18,
    'box-builder': 0.18,
    'neon-tube': 0.22,
    'magnetic-words': 0.22,
    'underline-chase': 0.22,
  }[norm] || 0.20;

  if (time < token.start) {
    return { opacity: 0, scaleMul: 0.8, dx: 0, dy: 10, blur: 0, rotAdd: 0, mask: 1, visible: false };
  }
  const p = clamp((time - token.start) / dur, 0, 1);

  if (norm === 'hype-drop') {
    const e = easeOutBack(p);
    const dropY = (1 - easeOutExpo(p)) * -40;
    const shake = (1 - p) * Math.sin(p * 32) * (hero ? 6 : 2);
    return {
      opacity: clamp(p * 4, 0, 1),
      scaleMul: lerp(hero ? 1.45 : 0.85, 1.0, e),
      dx: shake,
      dy: dropY,
      blur: (1 - p) * (hero ? 5 : 0),
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'candy-pop') {
    const e = easeOutBack(p);
    const idle = Math.sin((time - token.start) * 6) * 0.02;
    return {
      opacity: clamp(p * 3.5, 0, 1),
      scaleMul: lerp(0.55, 1.0, e) + idle,
      dx: 0,
      dy: (1 - e) * 14,
      blur: 0,
      rotAdd: (1 - e) * 8,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'flash-card') {
    const e = easeOutBack(p);
    const slideX = (1 - easeOutCubic(p)) * -35;
    const slideY = (1 - easeOutCubic(p)) * -18;
    return {
      opacity: clamp(p * 3.2, 0, 1),
      scaleMul: lerp(0.8, 1.0, e) + (hero ? 0.05 : 0),
      dx: slideX,
      dy: slideY,
      blur: 0,
      rotAdd: (1 - e) * -4,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'emoji-burst') {
    const e = easeOutBack(p);
    const slamUp = (1 - easeOutCubic(p)) * 26;
    return {
      opacity: clamp(p * 3.5, 0, 1),
      scaleMul: lerp(hero ? 0.75 : 0.9, 1.0, e),
      dx: 0,
      dy: slamUp,
      blur: (1 - p) * (hero ? 3 : 0),
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'chrome-jelly') {
    const e = easeOutBack(p);
    const wobble = Math.sin((time - token.start) * 7) * Math.exp(-p * 3) * 0.04;
    return {
      opacity: clamp(p * 3, 0, 1),
      scaleMul: lerp(0.65, 1.0, e) + wobble,
      dx: 0,
      dy: (1 - e) * 12,
      blur: (1 - p) * 2,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'text-rush') {
    const e = easeOutExpo(p);
    const rushX = (1 - e) * -80;
    return {
      opacity: clamp(p * 4, 0, 1),
      scaleMul: lerp(hero ? 1.3 : 0.9, 1.0, e),
      dx: rushX,
      dy: 0,
      blur: (1 - p) * (hero ? 7 : 3),
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'impact-slam') {
    const e = easeOutBack(p);
    const shake = (1 - p) * Math.sin(p * 28) * (hero ? 5 : 2);
    return {
      opacity: clamp(p * 3.5, 0, 1),
      scaleMul: lerp(hero ? 2.2 : 0.85, 1.0, e),
      dx: shake,
      dy: 0,
      blur: (1 - p) * (hero ? 4 : 0),
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'glass-caption') {
    const e = easeOutCubic(p);
    return {
      opacity: e,
      scaleMul: lerp(0.94, 1.0, e),
      dx: 0,
      dy: (1 - e) * 12,
      blur: (1 - e) * 3,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'marker-swipe') {
    const e = easeOutCubic(p);
    return {
      opacity: e,
      scaleMul: lerp(hero ? 0.9 : 0.96, 1.0, e),
      dx: (1 - e) * -8,
      dy: (1 - e) * 6,
      blur: 0,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'focus-rack') {
    const e = easeOutCubic(p);
    return {
      opacity: hero ? e : lerp(0.3, 0.45, e),
      scaleMul: lerp(0.92, 1.0, e),
      dx: 0,
      dy: 0,
      blur: hero ? (1 - e) * 5 : 3.5,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'elastic-pop') {
    const e = easeOutBack(p);
    return {
      opacity: clamp(p * 3, 0, 1),
      scaleMul: lerp(0.4, 1.0, e),
      dx: 0,
      dy: (1 - e) * 10,
      blur: 0,
      rotAdd: (1 - e) * (token.rot || 5) * 1.5,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'box-builder') {
    const e = easeOutExpo(p);
    return {
      opacity: clamp(p * 2.8, 0, 1),
      scaleMul: lerp(0.75, 1.0, e),
      dx: 0,
      dy: (1 - e) * 14,
      blur: 0,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'luxury-serif') {
    const e = easeOutCubic(p);
    return {
      opacity: e,
      scaleMul: lerp(0.96, 1.0, e),
      dx: 0,
      dy: (1 - e) * 14,
      blur: (1 - e) * 4,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'sticker-bomb') {
    const e = easeOutBack(p);
    return {
      opacity: clamp(p * 2.5, 0, 1),
      scaleMul: lerp(0.45, 1.0, e),
      dx: 0,
      dy: (1 - e) * -16,
      blur: 0,
      rotAdd: (1 - e) * 10,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'magnetic-words') {
    const e = easeOutExpo(p);
    return {
      opacity: clamp(p * 2, 0, 1),
      scaleMul: lerp(hero ? 0.6 : 0.9, 1.0, e),
      dx: 0,
      dy: (1 - e) * (hero ? 18 : 6),
      blur: 0,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'cutout-type') {
    const e = easeOutQuart(p);
    return {
      opacity: e,
      scaleMul: lerp(0.85, 1.0, e),
      dx: 0,
      dy: (1 - e) * 15,
      blur: 0,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'whisper-scream') {
    const e = hero ? easeOutBack(p) : easeOutCubic(p);
    return {
      opacity: clamp(p * 2.5, 0, 1),
      scaleMul: lerp(hero ? 1.8 : 0.85, 1.0, e),
      dx: (1 - e) * (hero ? 12 : -8),
      dy: 0,
      blur: (1 - p) * (hero ? 4 : 0),
      rotAdd: (1 - e) * (hero ? -4 : 0),
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'digital-scramble') {
    const e = easeOutCubic(p);
    return {
      opacity: e,
      scaleMul: 1.0,
      dx: (1 - e) * -12,
      dy: 0,
      blur: 0,
      rotAdd: 0,
      mask: 1 - e,
      visible: true,
    };
  }

  if (norm === 'underline-chase') {
    const e = easeOutQuart(p);
    return {
      opacity: e,
      scaleMul: lerp(0.94, 1.0, e),
      dx: (1 - e) * -10,
      dy: (1 - e) * 8,
      blur: 0,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'neon-tube') {
    // Electrical flicker on startup
    const flicker = p < 0.2 ? (p % 0.08 > 0.04 ? 0.9 : 0.1) : p < 0.4 ? (p % 0.1 > 0.05 ? 1 : 0.4) : 1;
    return {
      opacity: flicker,
      scaleMul: lerp(0.92, 1.0, easeOutBack(p)),
      dx: 0,
      dy: 0,
      blur: (1 - p) * 3,
      rotAdd: 0,
      mask: 0,
      visible: true,
    };
  }

  if (norm === 'terminal-error') {
    const e = easeOutCubic(p);
    return {
      opacity: e,
      scaleMul: 1.0,
      dx: (1 - e) * -15,
      dy: 0,
      blur: 0,
      rotAdd: 0,
      mask: 1 - e,
      visible: true,
    };
  }

  // gradient-sweep
  const e = easeOutExpo(p);
  return {
    opacity: clamp(p * 3, 0, 1),
    scaleMul: lerp(0.9, 1.0, e),
    dx: (1 - e) * -24,
    dy: 0,
    blur: 0,
    rotAdd: 0,
    mask: 0,
    visible: true,
  };
}

function mixLayouts(prev, next, mix, time, kind, changeTime, style = {}, env = null) {
  const prevMap = new Map(prev.map((t) => [t.id, t]));
  const nextIds = new Set(next.map((t) => t.id));
  const out = [];
  const e = easeOutBack(mix);
  const mp = MOTION_PRESETS[canonicalLayoutId(kind)];
  for (const t of next) {
    if (env) t.active = t.id === env.currentId;
    const enter = enterPose(t, time, kind, style, env);
    if (!enter.visible && time < t.start) continue;
    const p = prevMap.get(t.id);
    const token = { ...t, scaleMul: 1, dx: 0, dy: 0, blur: 0, rotAdd: 0, mask: 0 };
    if (p && mix < 1) {
      token.x = lerp(p.x, t.x, e);
      token.y = lerp(p.y, t.y, e);
      token.fs = lerp(p.fs, t.fs, e);
      token.w = lerp(p.w, t.w, e);
      token.h = lerp(p.h, t.h, e);
      token.rot = lerp(p.rot || 0, t.rot || 0, e);
      token.opacity = lerp(p.opacity, t.opacity, e);
    }
    token.opacity *= enter.opacity;
    token.scaleMul = enter.scaleMul;
    token.dx = enter.dx;
    token.dy = enter.dy;
    token.blur = enter.blur;
    token.rotAdd = enter.rotAdd;
    token.mask = enter.mask;
    if (mp) {
      for (const k in enter) if (!(k in token) || k === 'p') token[k] = enter[k];
    }
    out.push(token);
  }
  const exitT = 0.10;
  const exitMix = clamp((time - changeTime) / exitT, 0, 1);
  if (exitMix < 1) {
    for (const p of prev) {
      if (nextIds.has(p.id)) continue;
      const fade = 1 - easeOutCubic(exitMix);
      if (fade <= 0.02) continue;
      if (mp?.exit) {
        const gone = { ...p, opacity: p.opacity || 1, scaleMul: 1, dx: p.dx || 0, dy: p.dy || 0, blur: p.blur || 0, rotAdd: 0, mask: 0 };
        mp.exit(gone, exitMix, style);
        if ((gone.opacity || 0) > 0.02) out.push(gone);
        continue;
      }
      out.push({
        ...p,
        opacity: (p.opacity || 1) * fade,
        scaleMul: 0.9 + 0.1 * fade,
        dy: (p.dy || 0) + (1 - fade) * 8,
        dx: p.dx || 0,
        blur: p.blur || 0,
        rotAdd: 0,
        mask: 0,
      });
    }
  }
  return out;
}

export function tokensAtTime(ctx, cue, time, W, H, style) {
  const kind = style.dynamicLayout || 'impact-slam';
  const words = normalizeWords(cue);
  if (!words.length) return [];
  const phrase = activePhrase(words, time, kind, style);
  if (!phrase.length) return [];
  const env = {
    kind, W, H, style, time, phrase,
    heroId: pickHeroId(phrase),
    currentId: currentWordId(phrase, time),
  };
  const target = computeLayout(ctx, phrase, env);
  const changeTime = windowChangeTime(words, time, kind, style);
  const prevTime = Math.max(0, changeTime - 0.001);
  const prevPhrase = activePhrase(words, prevTime, kind, style);
  const prevEnv = {
    kind, W, H, style, time: prevTime, phrase: prevPhrase,
    heroId: pickHeroId(prevPhrase),
    currentId: currentWordId(prevPhrase, prevTime),
  };
  const prev = prevPhrase.length ? computeLayout(ctx, prevPhrase, prevEnv) : [];
  const norm = canonicalLayoutId(kind);
  const settle = rulesFor(kind, style).settle;
  const mix = clamp((time - changeTime) / settle, 0, 1);
  let tokens = mixLayouts(prev, target, mix, time, kind, changeTime, style, env);
  if (!tokens.length && phrase.length) {
    const rest = (phrase[0].start || 0) + 0.05;
    tokens = mixLayouts([], target, 1, rest, kind, changeTime, style, env);
  }
  const mp = MOTION_PRESETS[norm];
  for (const t of tokens) { t.now = time; if (t.active == null) t.active = t.id === env.currentId; }
  if (mp?.group && tokens.length) mp.group(tokens, time, env, motionKnobs(style));
  return tokens;
}

export function sampleCueForStyle(kind) {
  const norm = canonicalLayoutId(kind);
  const words = DYNAMIC_SAMPLES[norm] || DYNAMIC_SAMPLES[kind] || DYNAMIC_SAMPLES['impact-slam'];
  const step = 0.35;
  return {
    id: `dyn_${kind}`,
    start: 0,
    end: words.length * step + 0.45,
    text: words.join(' '),
    words: words.map((word, i) => ({
      word,
      start: i * step,
      end: i * step + step * 0.9,
    })),
  };
}

// ---------------------------------------------------------------------------
// Style Custom Canvas Painters (Backgrounds, Accents, Frames, FX)
// ---------------------------------------------------------------------------

function paintImpactSlamFX(ctx, tokens, style, scale1080, time) {
  const hero = tokens.find((t) => t.role === 'hero');
  if (!hero) return;
  const p = clamp((time - hero.start) / 0.22, 0, 1);
  if (p <= 0 || p >= 1) return;
  ctx.save();
  ctx.translate(hero.x + (hero.dx || 0), hero.y + (hero.dy || 0));
  ctx.globalAlpha *= (1 - p);
  ctx.strokeStyle = '#ff2828';
  ctx.lineWidth = Math.max(2, hero.fs * 0.06);
  // Radiating burst impact lines
  const count = 8;
  const rMin = hero.w * 0.55;
  const rMax = rMin + (1 - Math.pow(1 - p, 2)) * hero.fs * 1.5;
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2 + 0.2;
    ctx.beginPath();
    ctx.moveTo(Math.cos(angle) * rMin, Math.sin(angle) * rMin * 0.6);
    ctx.lineTo(Math.cos(angle) * rMax, Math.sin(angle) * rMax * 0.6);
    ctx.stroke();
  }
  ctx.restore();
}

function paintGlassCaptionFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const padX = Math.max(16, g.h * 0.22);
  const padY = Math.max(12, g.h * 0.16);
  const x = g.l - padX, y = g.t - padY, w = g.w + padX * 2, h = g.h + padY * 2;
  const radius = Math.min(18, padY * 1.2);
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);

  ctx.save();
  ctx.globalAlpha *= appear;

  // Glass card backdrop
  ctx.fillStyle = 'rgba(15, 20, 28, 0.72)';
  if (ctx.roundRect) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, radius);
    ctx.fill();
  } else {
    ctx.fillRect(x, y, w, h);
  }

  // Iridescent glass border
  const grad = ctx.createLinearGradient(x, y, x + w, y + h);
  grad.addColorStop(0, 'rgba(255, 255, 255, 0.6)');
  grad.addColorStop(0.3, 'rgba(56, 189, 248, 0.5)');
  grad.addColorStop(0.7, 'rgba(168, 85, 247, 0.5)');
  grad.addColorStop(1, 'rgba(255, 255, 255, 0.3)');
  ctx.strokeStyle = grad;
  ctx.lineWidth = Math.max(1.5, 2 * scale1080);
  if (ctx.roundRect) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, radius);
    ctx.stroke();
  }

  // Light sweep sheen
  const sweepProgress = (time * 1.2) % 2.5;
  if (sweepProgress < 1.2) {
    ctx.save();
    if (ctx.roundRect) {
      ctx.beginPath();
      ctx.roundRect(x, y, w, h, radius);
      ctx.clip();
    }
    const sweepX = x - w * 0.5 + sweepProgress * w * 1.5;
    const sweepGrad = ctx.createLinearGradient(sweepX, y, sweepX + w * 0.4, y + h);
    sweepGrad.addColorStop(0, 'rgba(255, 255, 255, 0)');
    sweepGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.28)');
    sweepGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = sweepGrad;
    ctx.fillRect(x, y, w, h);
    ctx.restore();
  }
  ctx.restore();
}

function paintMarkerSwipeFX(ctx, tokens, style, scale1080, time) {
  const hero = tokens.find((t) => t.role === 'hero');
  if (!hero) return;
  // The word lands first, then the marker paints behind it (imperfect
  // edges, chiselled ends) and the text flips to a readable colour as the
  // stroke covers it — see the 'marker' branch in paintToken.
  const p = clamp((time - hero.start - 0.06) / 0.24, 0, 1);
  if (p <= 0.01) return;
  const padX = hero.fs * 0.18;
  const padY = hero.fs * 0.12;
  const startX = hero.x + (hero.dx || 0) - hero.w / 2 - padX;
  const fullW = hero.w + padX * 2;
  const topY = hero.y + (hero.dy || 0) - hero.fs * 0.78 - padY;
  const h = hero.fs + padY * 1.8;
  const settle = 1 - 0.04 * Math.sin(Math.PI * clamp((time - hero.start - 0.3) / 0.16, 0, 1));

  ctx.save();
  ctx.globalAlpha *= (hero.opacity || 1) * 0.94;
  ctx.fillStyle = style.highlightColor || '#d9ff00';
  ctx.translate(startX + fullW / 2, topY + h / 2);
  ctx.scale(1, settle);
  ctx.translate(-(startX + fullW / 2), -(topY + h / 2));
  markerStroke(ctx, startX, topY, fullW, h, easeOutCubic(p), (hero.seed || 7) + Math.round(hero.start * 10), 1.2);
  ctx.restore();
}

function paintBoxBuilderFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const pad = Math.max(12, g.h * 0.16);
  const x = g.l - pad, y = g.t - pad, w = g.w + pad * 2, h = g.h + pad * 2;
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);

  ctx.save();
  ctx.globalAlpha *= appear;
  // Bounding guides
  ctx.strokeStyle = 'rgba(166, 255, 0, 0.4)';
  ctx.lineWidth = 1;
  ctx.strokeRect(x, y, w, h);

  // Corner transform handles
  ctx.fillStyle = '#a6ff00';
  const handle = Math.max(4, 5 * scale1080);
  ctx.fillRect(x - handle / 2, y - handle / 2, handle, handle);
  ctx.fillRect(x + w - handle / 2, y - handle / 2, handle, handle);
  ctx.fillRect(x - handle / 2, y + h - handle / 2, handle, handle);
  ctx.fillRect(x + w - handle / 2, y + h - handle / 2, handle, handle);
  ctx.restore();
}

function paintLuxurySerifFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);
  ctx.save();
  ctx.globalAlpha *= appear;

  // Golden accent crown / crest
  ctx.fillStyle = '#f5d77f';
  ctx.font = `900 ${Math.max(12, baseFont(style, 1080, 1920) * 0.45)}px sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('👑', g.cx, g.t - Math.max(14, g.h * 0.22));

  // Thin golden divider line
  ctx.strokeStyle = '#d4af37';
  ctx.lineWidth = Math.max(1.2, 1.8 * scale1080);
  const lineW = g.w * 0.85 * easeOutCubic(appear);
  ctx.beginPath();
  ctx.moveTo(g.cx - lineW / 2, g.b + Math.max(8, g.h * 0.12));
  ctx.lineTo(g.cx + lineW / 2, g.b + Math.max(8, g.h * 0.12));
  ctx.stroke();
  ctx.restore();
}

function paintDigitalScrambleFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);
  ctx.save();
  ctx.globalAlpha *= appear;

  // Digital progress bar underneath
  const barW = Math.max(120, g.w);
  const barH = Math.max(4, 5 * scale1080);
  const barX = g.cx - barW / 2;
  const barY = g.b + Math.max(10, g.h * 0.16);

  ctx.fillStyle = 'rgba(0, 240, 255, 0.2)';
  ctx.fillRect(barX, barY, barW, barH);

  const fillProg = clamp(((time * 1.5) % 3) / 2, 0.2, 0.95);
  ctx.fillStyle = '#00f0ff';
  ctx.fillRect(barX, barY, barW * fillProg, barH);

  ctx.font = `700 ${Math.max(10, 11 * scale1080)}px "JetBrains Mono", monospace`;
  ctx.fillStyle = '#00f0ff';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'top';
  ctx.fillText(`${Math.round(fillProg * 100)}%`, barX + barW + Math.max(28, 32 * scale1080), barY - 2);
  ctx.restore();
}

function paintUnderlineChaseFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);
  const firstT = tokens[0]?.start || 0;
  const lastT = tokens[tokens.length - 1]?.end || firstT + 1;
  const prog = clamp((time - firstT) / Math.max(0.2, lastT - firstT), 0, 1);

  ctx.save();
  ctx.globalAlpha *= appear;
  const lineY = g.b + Math.max(6, g.h * 0.1);
  const startX = g.l - 4;
  const totalW = g.w + 8;
  const currentX = startX + totalW * easeOutCubic(prog);

  // Glowing underline
  ctx.strokeStyle = style.highlightColor || '#b7ff19';
  ctx.shadowColor = style.highlightColor || '#b7ff19';
  ctx.shadowBlur = 10 * scale1080;
  ctx.lineWidth = Math.max(3, 4 * scale1080);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(startX, lineY);
  ctx.lineTo(currentX, lineY);
  ctx.stroke();

  // Leading tracker dot
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(currentX, lineY, Math.max(4, 5 * scale1080), 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function paintHypeDropFX(ctx, tokens, style, scale1080, time) {
  const hero = tokens.find((t) => t.role === 'hero');
  if (!hero) return;
  const p = clamp((time - hero.start) / 0.2, 0, 1);
  if (p <= 0.01) return;

  ctx.save();
  ctx.globalAlpha *= hero.opacity || 1;
  const pink = style.color2 || style.highlightColor || '#ff1379';
  const cx = hero.x + (hero.dx || 0);
  const cy = hero.y + (hero.dy || 0);

  // Pink impact splash lines
  ctx.strokeStyle = pink;
  ctx.lineWidth = Math.max(3, 4.5 * scale1080);
  ctx.lineCap = 'round';
  const splashProg = easeOutBack(p);

  const lines = [
    { x1: -hero.w * 0.55, y1: -hero.fs * 0.6, x2: -hero.w * 0.75 * splashProg, y2: -hero.fs * 0.9 * splashProg },
    { x1: hero.w * 0.55, y1: -hero.fs * 0.6, x2: hero.w * 0.78 * splashProg, y2: -hero.fs * 0.85 * splashProg },
    { x1: -hero.w * 0.5, y1: hero.fs * 0.2, x2: -hero.w * 0.7 * splashProg, y2: hero.fs * 0.4 * splashProg },
    { x1: hero.w * 0.52, y1: hero.fs * 0.15, x2: hero.w * 0.72 * splashProg, y2: hero.fs * 0.35 * splashProg },
  ];

  ctx.beginPath();
  for (const l of lines) {
    ctx.moveTo(cx + l.x1, cy + l.y1);
    ctx.lineTo(cx + l.x2, cy + l.y2);
  }
  ctx.stroke();

  // Subtle graffiti underline brush
  ctx.strokeStyle = pink;
  ctx.lineWidth = Math.max(4, 6 * scale1080);
  const underW = hero.w * 1.05 * easeOutCubic(p);
  ctx.beginPath();
  ctx.moveTo(cx - underW / 2, cy + hero.fs * 0.22);
  ctx.lineTo(cx + underW / 2, cy + hero.fs * 0.18);
  ctx.stroke();

  ctx.restore();
}

function paintCandyPopFX(ctx, tokens, style, scale1080, time) {
  const hero = tokens.find((t) => t.role === 'hero') || tokens[0];
  if (!hero) return;
  const p = clamp((time - hero.start) / 0.25, 0, 1);
  if (p <= 0.01) return;

  ctx.save();
  ctx.globalAlpha *= hero.opacity || 1;
  const cx = hero.x + (hero.dx || 0);
  const cy = hero.y + (hero.dy || 0);
  const popScale = easeOutBack(p);

  // Orbiting sparkles (✦, ★, mini hearts)
  const sparkles = [
    { x: -hero.w * 0.58, y: -hero.fs * 0.7, char: '✦', color: '#ffe600', size: 20 },
    { x: hero.w * 0.6, y: -hero.fs * 0.65, char: '★', color: '#ff499e', size: 18 },
    { x: hero.w * 0.62, y: hero.fs * 0.2, char: '✦', color: '#00f5d4', size: 16 },
    { x: -hero.w * 0.52, y: hero.fs * 0.25, char: '♥', color: '#ff499e', size: 17 },
  ];

  for (const sp of sparkles) {
    ctx.save();
    ctx.translate(cx + sp.x * popScale, cy + sp.y * popScale);
    ctx.scale(popScale, popScale);
    ctx.fillStyle = sp.color;
    ctx.font = `900 ${Math.max(12, sp.size * scale1080)}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = sp.color;
    ctx.shadowBlur = 8 * scale1080;
    ctx.fillText(sp.char, 0, 0);
    ctx.restore();
  }

  ctx.restore();
}

function paintFlashCardFX(ctx, tokens, style, scale1080, time) {
  // Flash cards draw their physical card backgrounds inside paintToken per word
}

function paintEmojiBurstFX(ctx, tokens, style, scale1080, time) {
  const hero = tokens.find((t) => t.role === 'hero');
  if (!hero) return;
  const p = clamp((time - hero.start) / 0.24, 0, 1);
  if (p <= 0.01) return;

  ctx.save();
  ctx.globalAlpha *= hero.opacity || 1;
  const cx = hero.x + (hero.dx || 0);
  const cy = hero.y + (hero.dy || 0);
  const popScale = easeOutBack(p);

  // Contextual stickers surrounding the hero keyword
  const stickers = [
    { x: -hero.w * 0.62, y: -hero.fs * 0.45, emoji: '😱', size: 34, rot: -12 },
    { x: hero.w * 0.64, y: -hero.fs * 0.2, emoji: '🔥', size: 36, rot: 15 },
    { x: hero.w * 0.45, y: -hero.fs * 0.85, emoji: '⚡', size: 26, rot: -8 },
    { x: -hero.w * 0.35, y: -hero.fs * 0.88, emoji: '⭐', size: 24, rot: 10 },
  ];

  for (const st of stickers) {
    ctx.save();
    ctx.translate(cx + st.x * popScale, cy + st.y * popScale);
    ctx.rotate((st.rot * Math.PI) / 180);
    ctx.scale(popScale, popScale);
    ctx.font = `${Math.max(14, st.size * scale1080)}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = 'rgba(0,0,0,0.6)';
    ctx.shadowBlur = 10 * scale1080;
    ctx.fillText(st.emoji, 0, 0);
    ctx.restore();
  }

  // Glowing brush underline under the hero keyword
  ctx.strokeStyle = '#ffe600';
  ctx.shadowColor = '#ff5400';
  ctx.shadowBlur = 12 * scale1080;
  ctx.lineWidth = Math.max(3.5, 5 * scale1080);
  ctx.lineCap = 'round';
  const underW = hero.w * 1.1 * easeOutCubic(p);
  ctx.beginPath();
  ctx.moveTo(cx - underW / 2, cy + hero.fs * 0.18);
  ctx.lineTo(cx + underW / 2, cy + hero.fs * 0.18);
  ctx.stroke();

  ctx.restore();
}

function paintChromeJellyFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);
  if (appear <= 0.01) return;

  ctx.save();
  ctx.globalAlpha *= appear;

  // Horizontal specular glossy sweep
  const sweepProgress = (time * 1.4) % 2.5;
  const sweepX = g.l - g.w * 0.3 + sweepProgress * g.w * 1.2;
  const sweepGrad = ctx.createLinearGradient(sweepX, g.t, sweepX + g.w * 0.3, g.b);
  sweepGrad.addColorStop(0, 'rgba(255, 255, 255, 0)');
  sweepGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.45)');
  sweepGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');

  // Chrome iridescent outer aura
  ctx.shadowColor = '#00f2fe';
  ctx.shadowBlur = 18 * scale1080;
  ctx.fillStyle = sweepGrad;
  ctx.fillRect(g.l - 10, g.t - 10, g.w + 20, g.h + 20);
  ctx.restore();
}

function paintTextRushFX(ctx, tokens, style, scale1080, time) {
  const hero = tokens.find((t) => t.role === 'hero') || tokens[0];
  if (!hero) return;
  const p = clamp((time - hero.start) / 0.2, 0, 1);
  if (p <= 0.01) return;

  ctx.save();
  ctx.globalAlpha *= hero.opacity || 1;
  const cx = hero.x + (hero.dx || 0);
  const cy = hero.y + (hero.dy || 0);

  // Directional horizontal speed streaks
  const orange = style.color2 || style.highlightColor || '#ff5500';
  ctx.strokeStyle = orange;
  ctx.lineWidth = Math.max(2, 3 * scale1080);
  ctx.lineCap = 'round';
  const streakProg = easeOutExpo(p);

  const streakOffsets = [-hero.fs * 0.7, -hero.fs * 0.35, 0, hero.fs * 0.2];
  ctx.beginPath();
  for (let i = 0; i < streakOffsets.length; i++) {
    const yOff = streakOffsets[i];
    const len = (hero.w * 0.8 + i * 20) * streakProg;
    ctx.moveTo(cx - hero.w * 0.7 - len, cy + yOff);
    ctx.lineTo(cx - hero.w * 0.5, cy + yOff);
  }
  ctx.stroke();

  ctx.restore();
}

function paintNeonTubeFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const padX = Math.max(20, g.h * 0.28);
  const padY = Math.max(16, g.h * 0.24);
  const x = g.l - padX, y = g.t - padY, w = g.w + padX * 2, h = g.h + padY * 2;
  const radius = Math.min(22, padY * 1.3);
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);

  ctx.save();
  ctx.globalAlpha *= appear;
  // Neon tube outer box
  const color = style.highlightColor || '#ff2bd6';
  ctx.strokeStyle = color;
  ctx.shadowColor = color;
  ctx.shadowBlur = 18 * scale1080;
  ctx.lineWidth = Math.max(3, 4 * scale1080);
  if (ctx.roundRect) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, radius);
    ctx.stroke();
  } else {
    ctx.strokeRect(x, y, w, h);
  }
  ctx.restore();
}

function paintVhsTrackFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const padX = g.h * 0.22, padY = g.h * 0.2;
  const x = g.l - padX, y = g.t - padY, w = g.w + padX * 2, h = g.h + padY * 2;
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);

  ctx.save();
  ctx.globalAlpha *= appear;
  // Tape strip behind the words — dark enough to carry cream type on any footage.
  ctx.fillStyle = 'rgba(8, 6, 12, 0.46)';
  ctx.fillRect(x, y, w, h);
  ctx.beginPath();
  ctx.rect(x, y, w, h);
  ctx.clip();
  // Scanlines
  const line = Math.max(1, 2 * scale1080);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.18)';
  for (let ly = y; ly < y + h; ly += line * 2) ctx.fillRect(x, ly, w, line);
  // Tracking band drifting up the strip
  const bandH = Math.max(2, h * 0.12);
  const bandY = y + h - ((time * h * 0.5) % (h + bandH * 2));
  ctx.fillStyle = 'rgba(255, 255, 255, 0.07)';
  ctx.fillRect(x, bandY, w, bandH);
  // Head-switch noise at the bottom edge
  ctx.fillStyle = 'rgba(255, 255, 255, 0.14)';
  ctx.fillRect(x, y + h - line, w, line);
  ctx.restore();
}

function paintInkScriptFX(ctx, tokens, style, scale1080, time) {
  const hero = tokens.find((t) => t.role === 'hero');
  if (!hero) return;
  const p = easeOutCubic(clamp((time - hero.start) / 0.34, 0, 1));
  if (p <= 0.01) return;
  const fullW = hero.w * 1.08;
  const x0 = hero.x - fullW / 2;
  const w = fullW * p;
  const yBase = hero.y + hero.fs * 0.16;
  const lift = hero.fs * 0.1;

  ctx.save();
  ctx.globalAlpha *= (hero.opacity || 1) * 0.92;
  ctx.strokeStyle = style.highlightColor || '#f4cf7d';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.shadowColor = 'rgba(0, 0, 0, 0.45)';
  ctx.shadowBlur = hero.fs * 0.12;
  // Pen stroke swash under the script word
  ctx.lineWidth = Math.max(1.5, hero.fs * 0.05);
  ctx.beginPath();
  ctx.moveTo(x0, yBase);
  ctx.quadraticCurveTo(x0 + w * 0.5, yBase + lift, x0 + w, yBase - lift * 0.5);
  ctx.stroke();
  // Lighter second pass, the way a nib doubles back
  ctx.globalAlpha *= 0.45;
  ctx.lineWidth = Math.max(1, hero.fs * 0.022);
  ctx.beginPath();
  ctx.moveTo(x0 + w * 0.05, yBase + lift * 0.6);
  ctx.quadraticCurveTo(x0 + w * 0.55, yBase + lift * 1.3, x0 + w * 0.97, yBase + lift * 0.15);
  ctx.stroke();
  ctx.restore();
}

function paintTerminalErrorFX(ctx, tokens, style, scale1080, time) {
  const g = groupBounds(tokens);
  if (g.w < 6 || g.h < 6) return;
  const pad = Math.max(16, g.h * 0.22);
  const x = g.l - pad, y = g.t - pad, w = g.w + pad * 2, h = g.h + pad * 2;
  const appear = Math.max(...tokens.map((t) => t.opacity || 0), 0);

  ctx.save();
  ctx.globalAlpha *= appear;
  ctx.fillStyle = 'rgba(28, 6, 6, 0.88)';
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = '#ff2d2d';
  ctx.lineWidth = 2;
  ctx.strokeRect(x, y, w, h);

  // Warning icon
  ctx.font = `700 ${Math.max(12, 14 * scale1080)}px sans-serif`;
  ctx.fillStyle = '#ff2d2d';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('⚠️', x + 6, y + 6);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Paint Token
// ---------------------------------------------------------------------------
function paintToken(ctx, token, style, scale1080) {
  if ((token.opacity || 0) <= 0.01) return;
  ctx.save();
  ctx.translate(token.x + (token.dx || 0), token.y + (token.dy || 0));
  ctx.rotate(((token.rot || 0) + (token.rotAdd || 0)) * Math.PI / 180);
  const s = Math.max(0.001, (token.scale || 1) * (token.scaleMul || 1));
  ctx.scale(s, s);
  ctx.globalAlpha *= token.opacity;

  if ((token.blur || 0) > 0.25) ctx.filter = `blur(${token.blur * scale1080}px)`;
  if ((token.mask || 0) > 0.02) {
    ctx.beginPath();
    ctx.rect(-token.w, -token.h * 1.1 + token.h * 1.4 * (1 - token.mask), token.w * 2, token.h * 2.2);
    ctx.clip();
  }

  setFont(ctx, token.fs, style, token);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  const fill = token.fill || style.color || '#ffffff';

  const motionPainter = MOTION_PAINTERS[token.effect];
  if (motionPainter) {
    motionPainter(ctx, token, style, scale1080, fill);
    ctx.restore();
    return;
  }

  // Hype Drop
  if (token.effect === 'hype-drop') {
    const isHero = token.role === 'hero';
    const textColor = isHero ? (token.accentColor || '#ff1379') : '#ffffff';
    // 4-step dark extrusion shadow
    ctx.save();
    ctx.fillStyle = 'rgba(0, 0, 0, 0.9)';
    for (let offset = 4; offset >= 1; offset--) {
      ctx.fillText(token.text, offset * 1.5, offset * 1.5);
    }
    ctx.restore();
    // Heavy stroke
    ctx.lineWidth = Math.max(3, token.fs * 0.12);
    ctx.strokeStyle = '#000000';
    ctx.lineJoin = 'round';
    ctx.miterLimit = 2;
    ctx.strokeText(token.text, 0, 0);
    // Fill
    ctx.fillStyle = textColor;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Candy Pop
  if (token.effect === 'candy-pop') {
    const bubbleColor = token.candyColor || '#ff499e';
    // Thick dark bubble outline
    ctx.lineWidth = Math.max(4, token.fs * 0.14);
    ctx.strokeStyle = '#0a0a0c';
    ctx.lineJoin = 'round';
    ctx.miterLimit = 2;
    ctx.strokeText(token.text, 0, 0);

    // 3D glossy gradient fill
    const grad = ctx.createLinearGradient(0, -token.fs * 0.8, 0, 0);
    grad.addColorStop(0, '#ffffff');
    grad.addColorStop(0.25, bubbleColor);
    grad.addColorStop(1, bubbleColor);
    ctx.fillStyle = grad;
    ctx.fillText(token.text, 0, 0);

    // Specular highlight dot / arc
    ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
    ctx.fillText(token.text, 0, -token.fs * 0.08);
    ctx.fillStyle = bubbleColor;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Flash Card
  if (token.effect === 'flash-card') {
    const theme = token.cardTheme || { bg: '#ccff00', text: '#000000' };
    const padX = token.fs * 0.32, padY = token.fs * 0.2;
    const x = -token.w / 2 - padX, y = -token.fs * 0.82 - padY * 0.25;
    const w = token.w + padX * 2, h = token.fs + padY * 2;

    // Card drop shadow
    ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
    ctx.shadowBlur = 12 * scale1080;
    ctx.shadowOffsetY = 4 * scale1080;

    // Card background
    ctx.fillStyle = theme.bg;
    if (ctx.roundRect) {
      ctx.beginPath();
      ctx.roundRect(x, y, w, h, Math.max(8, 12 * scale1080));
      ctx.fill();
    } else {
      ctx.fillRect(x, y, w, h);
    }

    // Card border
    ctx.shadowBlur = 0;
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.25)';
    ctx.lineWidth = Math.max(1.5, 2 * scale1080);
    if (ctx.roundRect) {
      ctx.beginPath();
      ctx.roundRect(x, y, w, h, Math.max(8, 12 * scale1080));
      ctx.stroke();
    } else {
      ctx.strokeRect(x, y, w, h);
    }

    // Text inside card
    ctx.fillStyle = theme.text;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Emoji Burst
  if (token.effect === 'emoji-burst') {
    const isHero = token.role === 'hero';
    if (isHero) {
      // Gradient yellow/orange fill
      const grad = ctx.createLinearGradient(0, -token.fs * 0.8, 0, 0);
      grad.addColorStop(0, '#ffe600');
      grad.addColorStop(1, '#ff5400');
      // Heavy dark outline
      ctx.lineWidth = Math.max(3.5, token.fs * 0.14);
      ctx.strokeStyle = '#000000';
      ctx.lineJoin = 'round';
      ctx.miterLimit = 2;
      ctx.strokeText(token.text, 0, 0);
      ctx.fillStyle = grad;
      ctx.fillText(token.text, 0, 0);
    } else {
      ctx.fillStyle = '#ffffff';
      ctx.shadowColor = 'rgba(0,0,0,0.7)';
      ctx.shadowBlur = 8 * scale1080;
      ctx.fillText(token.text, 0, 0);
    }
    ctx.restore();
    return;
  }

  // Chrome Jelly
  if (token.effect === 'chrome-jelly') {
    // Iridescent metallic gradient
    const grad = ctx.createLinearGradient(-token.w / 2, -token.fs * 0.8, token.w / 2, 0);
    grad.addColorStop(0, '#ffffff');
    grad.addColorStop(0.2, '#00f2fe');
    grad.addColorStop(0.5, '#ffffff');
    grad.addColorStop(0.75, '#4facfe');
    grad.addColorStop(1, '#f72585');

    // Glossy rim stroke
    ctx.lineWidth = Math.max(2, token.fs * 0.08);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
    ctx.strokeText(token.text, 0, 0);

    ctx.fillStyle = grad;
    ctx.shadowColor = '#00f2fe';
    ctx.shadowBlur = 14 * scale1080;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Text Rush
  if (token.effect === 'text-rush') {
    const isHero = token.role === 'hero';
    const textColor = isHero ? (token.accentColor || '#ff5500') : '#ffffff';
    // Racing stroke
    ctx.lineWidth = Math.max(3, token.fs * 0.12);
    ctx.strokeStyle = '#000000';
    ctx.lineJoin = 'round';
    ctx.miterLimit = 2;
    ctx.strokeText(token.text, 0, 0);
    ctx.fillStyle = textColor;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Box Builder block
  if (token.effect === 'box') {
    const padX = token.fs * 0.25, padY = token.fs * 0.16;
    ctx.fillStyle = token.role === 'hero' ? (style.highlightColor || '#a6ff00') : token.line === 0 ? '#ffffff' : '#7c3aed';
    const x = -token.w / 2 - padX, y = -token.fs * 0.82 - padY * 0.3;
    const w = token.w + padX * 2, h = token.fs + padY * 2;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = token.role === 'hero' || token.line === 0 ? '#0a0a0a' : '#ffffff';
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Sticker Bomb badge
  if (token.effect === 'sticker') {
    const padX = token.fs * 0.28, padY = token.fs * 0.16;
    const x = -token.w / 2 - padX, y = -token.fs * 0.82 - padY * 0.3;
    const w = token.w + padX * 2, h = token.fs + padY * 2;
    // White die-cut border
    ctx.fillStyle = '#ffffff';
    if (ctx.roundRect) {
      ctx.beginPath();
      ctx.roundRect(x - 3, y - 3, w + 6, h + 6, token.fs * 0.25);
      ctx.fill();
    } else {
      ctx.fillRect(x - 3, y - 3, w + 6, h + 6);
    }
    // Color fill
    ctx.fillStyle = token.role === 'hero' ? '#2b6cff' : '#ffe600';
    if (ctx.roundRect) {
      ctx.beginPath();
      ctx.roundRect(x, y, w, h, token.fs * 0.2);
      ctx.fill();
    } else {
      ctx.fillRect(x, y, w, h);
    }
    ctx.fillStyle = token.role === 'hero' ? '#ffffff' : '#111111';
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Magnetic Words chip
  if (token.effect === 'magnetic') {
    const padX = token.fs * 0.28, padY = token.fs * 0.18;
    const x = -token.w / 2 - padX, y = -token.fs * 0.82 - padY * 0.3;
    const w = token.w + padX * 2, h = token.fs + padY * 2;
    if (token.role === 'hero') {
      ctx.shadowColor = '#c6ff00';
      ctx.shadowBlur = 18 * scale1080;
      ctx.fillStyle = '#c6ff00';
    } else {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
    }
    if (ctx.roundRect) {
      ctx.beginPath();
      ctx.roundRect(x, y, w, h, token.fs * 0.25);
      ctx.fill();
    } else {
      ctx.fillRect(x, y, w, h);
    }
    ctx.shadowBlur = 0;
    ctx.fillStyle = token.role === 'hero' ? '#0a0a0a' : '#888888';
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Neon Tube letter glow
  if (token.effect === 'neon') {
    const neonColor = token.role === 'hero' ? (style.highlightColor || '#00f0ff') : (style.color || '#ff2bd6');
    ctx.shadowColor = neonColor;
    ctx.shadowBlur = 16 * scale1080;
    ctx.fillStyle = '#ffffff';
    ctx.fillText(token.text, 0, 0);
    ctx.strokeStyle = neonColor;
    ctx.lineWidth = Math.max(2, token.fs * 0.08);
    ctx.strokeText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Retro VHS chromatic split — ghosting instead of glow
  if (token.effect === 'vhs') {
    const split = Math.max(1, token.fs * 0.045);
    const drift = Math.sin(token.x * 0.6 + (token.start || 0) * 30) * split * 0.4;
    ctx.save();
    ctx.globalAlpha *= 0.45;
    ctx.fillStyle = '#3ad7ff';
    ctx.fillText(token.text, -split + drift, 0);
    ctx.fillStyle = '#ff4d6d';
    ctx.fillText(token.text, split - drift, 0);
    ctx.restore();
    if (style.outline !== false) {
      ctx.lineWidth = Math.max(1, token.fs * 0.06 * (style.outlineW != null ? style.outlineW : 1));
      ctx.strokeStyle = style.outlineColor || 'rgba(10, 6, 14, 0.9)';
      ctx.lineJoin = 'round';
      ctx.miterLimit = 2;
      ctx.strokeText(token.text, 0, 0);
    }
    ctx.fillStyle = fill;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Cursive Ink — soft shadow only, the swash does the accenting
  if (token.effect === 'ink') {
    ctx.shadowColor = 'rgba(0, 0, 0, 0.55)';
    ctx.shadowBlur = token.fs * 0.16;
    ctx.shadowOffsetY = token.fs * 0.05;
    ctx.fillStyle = fill;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Marker Swipe — the hero sits on its own swipe, so it cannot reuse that color
  if (token.effect === 'marker') {
    if (token.role === 'hero') {
      const covered = clamp(((token.now ?? token.start) - token.start - 0.06) / 0.24, 0, 1) >= 0.5;
      ctx.fillStyle = covered ? (style.highlightTextColor || readableOn(style.highlightColor || '#d9ff00')) : fill;
      if (!covered) { ctx.shadowColor = 'rgba(0, 0, 0, 0.5)'; ctx.shadowBlur = token.fs * 0.14; }
    } else {
      if (style.outline) {
        ctx.lineWidth = Math.max(1.4, token.fs * 0.1 * (style.outlineW != null ? style.outlineW : 1));
        ctx.strokeStyle = style.outlineColor || '#000000';
        ctx.lineJoin = 'round';
        ctx.miterLimit = 2;
        ctx.strokeText(token.text, 0, 0);
      }
      ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
      ctx.shadowBlur = token.fs * 0.14;
      ctx.fillStyle = fill;
    }
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Gradient Sweep fill
  if (token.effect === 'gradient') {
    const grad = ctx.createLinearGradient(-token.w / 2, 0, token.w / 2, 0);
    grad.addColorStop(0, '#ff2bd6');
    grad.addColorStop(0.35, '#ff7b00');
    grad.addColorStop(0.7, '#ffe600');
    grad.addColorStop(1, '#00f0ff');
    ctx.fillStyle = grad;
    ctx.fillText(token.text, 0, 0);
    ctx.restore();
    return;
  }

  // Default / other styles
  if (style.dropShadow && !style.glow) {
    ctx.shadowColor = 'rgba(0,0,0,0.6)';
    ctx.shadowBlur = token.fs * 0.18;
    ctx.shadowOffsetX = token.fs * 0.04;
    ctx.shadowOffsetY = token.fs * 0.08;
  }
  if (style.glow || token.effect === 'glow') {
    ctx.shadowColor = fill;
    ctx.shadowBlur = (style.glowSize || 18) * scale1080 * 1.5;
  }

  const wantOutline = style.outline && (style.outlineW == null || style.outlineW > 0.05);
  if (wantOutline) {
    ctx.lineWidth = Math.max(1.4, token.fs * 0.1 * (style.outlineW != null ? style.outlineW : 1));
    ctx.strokeStyle = style.outlineColor || '#000000';
    ctx.lineJoin = 'round';
    ctx.miterLimit = 2;
    ctx.strokeText(token.text, 0, 0);
  }
  ctx.fillStyle = fill;
  ctx.fillText(token.text, 0, 0);
  ctx.restore();
}

export function drawDynamicCaption(ctx, cue, srcT, W, H, style) {
  if (canonicalLayoutId(style.dynamicLayout) === 'flying-type') {
    return drawFlyingTypeCaption(ctx, cue, srcT, W, H, style);
  }
  const tokens = tokensAtTime(ctx, cue, srcT, W, H, style);
  if (!tokens.length) return null;
  const remaining = (cue.end ?? cue.endTime ?? srcT + 1) - srcT;
  const norm = canonicalLayoutId(style.dynamicLayout);
  const mp = MOTION_PRESETS[norm];
  const exitDur = mp?.exitDur || 0.12;
  const exitMix = remaining < exitDur ? 1 - clamp(remaining / exitDur, 0, 1) : 0;
  const exitFade = mp?.exit ? 1 : (exitMix > 0 ? 1 - easeInCubicKit(exitMix) : 1);
  if (mp?.exit && exitMix > 0) for (const t of tokens) mp.exit(t, exitMix, style);
  const scale1080 = H / 1080;

  ctx.save();
  ctx.globalAlpha *= exitFade;

  // Backgrounds & Custom FX layers
  if (mp) { if (mp.fx) mp.fx(ctx, tokens, style, scale1080, srcT, { exitMix, W, H, time: srcT }); }
  else if (norm === 'hype-drop') paintHypeDropFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'candy-pop') paintCandyPopFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'flash-card') paintFlashCardFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'emoji-burst') paintEmojiBurstFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'chrome-jelly') paintChromeJellyFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'text-rush') paintTextRushFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'impact-slam') paintImpactSlamFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'glass-caption') paintGlassCaptionFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'marker-swipe') paintMarkerSwipeFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'box-builder') paintBoxBuilderFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'luxury-serif') paintLuxurySerifFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'digital-scramble') paintDigitalScrambleFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'underline-chase') paintUnderlineChaseFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'neon-tube') paintNeonTubeFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'terminal-error') paintTerminalErrorFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'vhs-track') paintVhsTrackFX(ctx, tokens, style, scale1080, srcT);
  else if (norm === 'ink-script') paintInkScriptFX(ctx, tokens, style, scale1080, srcT);

  // Paint Tokens
  for (const token of tokens) paintToken(ctx, token, style, scale1080);
  ctx.restore();

  const g = groupBounds(tokens);
  const pad = Math.max(8, baseFont(style, W, H) * 0.35);
  return { x: g.l - pad, y: g.t - pad, w: g.w + pad * 2, h: g.h + pad * 2 };
}
